import{_ as n,C as s,o as u,c as e,j as i,E as l,a as t,a2 as r}from"./chunks/framework.C21TwvGF.js";const M=JSON.parse(`{"title":"1-dars (Mentor). Ma’lumot tushunchasi, uning turlari va DIKW modeli","description":"","frontmatter":{"title":"1-dars (Mentor). Ma’lumot tushunchasi, uning turlari va DIKW modeli","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"week":{"n":1,"link":"/mentor/9-sinf-bi/hafta-01/"},"g":1,"title":"Ma’lumot tushunchasi, uning turlari va DIKW modeli","lead":"Raqamlar olamiga kirish: xom ma'lumotlar qanday qilib foydali axborot, chuqur bilim va oqilona qarorlarga aylanishini DIKW piramidasi orqali kashf eting.","slide":"/slaydlar/9-sinf-bi/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-bi/hafta-01/dars-1-test.html","student_link":"/9-sinf-bi/hafta-01/dars-1","tabs":[{"g":1,"link":"/mentor/9-sinf-bi/hafta-01/dars-1","current":true},{"g":2,"link":"/mentor/9-sinf-bi/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-bi/hafta-01/dars-3","current":false}],"prev":null,"next":{"g":2,"title":"Business Intelligence (BI) asoslari: Katta to'rtlik va hayotiy sikl","link":"/mentor/9-sinf-bi/hafta-01/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-01/dars-1.md","filePath":"mentor/9-sinf-bi/hafta-01/dars-1.md"}`),d={name:"mentor/9-sinf-bi/hafta-01/dars-1.md"},m={class:"blk"},h={id:"dars-rejasi",tabindex:"-1"},q={class:"blk"},k={id:"mentor-konspekti",tabindex:"-1"},g={class:"blk"},y={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},v={id:"tezkor-nazorat-savollari",tabindex:"-1"},f={class:"blk"},c={id:"uyga-vazifa",tabindex:"-1"};function z(p,a,_,x,D,I){const o=s("Icon");return u(),e("div",null,[i("div",m,[i("h2",h,[l(o,{name:"file-text"}),a[0]||(a[0]=t(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga ma’lumot (data) tushunchasi, uning zamonaviy iqtisodiyotdagi strategik o&#39;rni, ma’lumotlarning asosiy turlari (miqdoriy, sifat, strukturaviy, yarim-strukturaviy, nostrukturaviy) hamda DIKW piramidasi (Data → Information → Knowledge → Wisdom) mantiqiy zanjirini tushuntirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar xom ma&#39;lumot va mazmunli axborot farqini biladi; ma&#39;lumotlarni toifalarga ajrata oladi; DIKW piramidasi bosqichlarini real biznes misolida amalda tahlil qila oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>Tashkiliy qism va kirish: 10 daqiqa</li><li>Nazariy konspekt (Ma&#39;lumot tushunchasi va turlari): 20 daqiqa</li><li>DIKW modeli va real keyslar tahlili: 20 daqiqa</li><li>Amaliy mashg&#39;ulot va topshiriqlar: 20 daqiqa</li><li>Tezkor nazorat va xulosa: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",q,[i("h2",k,[l(o,{name:"file-text"}),a[3]||(a[3]=t(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-ma-lumot-data-nima" tabindex="-1">1. Ma’lumot (data) nima? <a class="header-anchor" href="#_1-ma-lumot-data-nima" aria-label="Permalink to &quot;1. Ma’lumot (data) nima?&quot;">​</a></h3><p>Ma’lumot (data) — bu real hayotdagi hodisalar, jarayonlar yoki obyektlar haqida o‘lchangan, qayd etilgan yoki yig‘ilgan xom faktlar majmuasidir. Ma’lumot o‘z holicha faqat &quot;xom material&quot; hisoblanadi. Masalan, shunchaki <code>25</code>, <code>Toshkent</code>, <code>olma</code> so&#39;zlari yoki raqamlari alohida olinganda hech qanday foydali xulosa bermaydi. Ular tahlil qilinib, kontekst berilgandagina qaror qabul qilishga yordam beradigan qimmatli resursga aylanadi.</p><h3 id="_2-ma-lumotlarning-asosiy-tasnifi" tabindex="-1">2. Ma’lumotlarning asosiy tasnifi <a class="header-anchor" href="#_2-ma-lumotlarning-asosiy-tasnifi" aria-label="Permalink to &quot;2. Ma’lumotlarning asosiy tasnifi&quot;">​</a></h3><p>Rasmiy o&#39;quv qo&#39;llanmaga muvofiq, ma&#39;lumotlar quyidagi turlarga bo&#39;linadi:</p><ol><li><strong>Miqdoriy ma’lumotlar (Quantitative Data):</strong> Sonlar va o&#39;lchovlar bilan ifodalanadi. <ul><li><em>Diskret (Discrete):</em> Butun sonlar (masalan, do&#39;konga kirgan 14 nafar xaridor, 5 dona noutbuk).</li><li><em>Uzluksiz (Continuous):</em> Ma&#39;lum shkala bo&#39;yicha uzluksiz o&#39;lchanadigan qiymatlar (masalan, havo harorati 24.5°C, og&#39;irlik 72.3 kg).</li></ul></li><li><strong>Sifat ma’lumotlar (Qualitative Data):</strong> Sonlarda emas, balki so&#39;zlar, toifalar va tavsiflar orqali ifodalanadi (mijoz sharhlari: &quot;juda yoqdi&quot;, mahsulot rangi: &quot;qizil&quot;, holati: &quot;yaroqli&quot;).</li><li><strong>Strukturaviy ma’lumotlar (Structured Data):</strong> Aniq qator va ustunlarga ega jadvallar (Excel, SQL ma&#39;lumotlar bazalari). Oson qidiriladi va tahlil qilinadi.</li><li><strong>Nostrukturaviy ma’lumotlar (Unstructured Data):</strong> Oldindan belgilangan jadval shakliga ega bo&#39;lmagan ma&#39;lumotlar (rasmlar, audio yozuvlar, PDF hujjatlar, xabarlar). Bugungi kunda dunyodagi barcha ma&#39;lumotlarning 80% dan ortig&#39;i nostrukturaviydir!</li><li><strong>Yarim-strukturaviy ma’lumotlar (Semi-Structured Data):</strong> Qat&#39;iy jadval emas, lekin ma&#39;lumotni belgilab turuvchi teglar mavjud (JSON, XML fayllar).</li></ol><h3 id="_3-dikw-piramidasi-ma-lumotlar-evolyutsiyasi" tabindex="-1">3. DIKW Piramidasi (Ma&#39;lumotlar evolyutsiyasi) <a class="header-anchor" href="#_3-dikw-piramidasi-ma-lumotlar-evolyutsiyasi" aria-label="Permalink to &quot;3. DIKW Piramidasi (Ma&#39;lumotlar evolyutsiyasi)&quot;">​</a></h3><p>DIKW piramidasi xom faktlarning qanday qilib oqilona qarorga aylanishini ko&#39;rsatuvchi klassik modeldir:</p><ul><li><strong>Data (Ma’lumot):</strong> Kontekstsiz xom fakt. Misol: <code>39</code> raqami.</li><li><strong>Information (Axborot):</strong> Ma&#39;lumotga &quot;kim, nima, qachon, qayerda?&quot; degan kontekst berilishi. Misol: &quot;Bugun Buxoroda havo harorati 39°C ga yetdi&quot;.</li><li><strong>Knowledge (Bilim):</strong> Tajriba va tahlil asosida hosil qilingan qonuniyat (&quot;Nega?&quot;). Misol: &quot;Buxoroda harorat 38°C dan oshganda, shahar bo&#39;ylab muzdek ichimliklar va muzqaymoqqa bo&#39;lgan talab 60% ga ortadi&quot;.</li><li><strong>Wisdom (Donolik):</strong> Bilimga asoslanib to&#39;g&#39;ri, istiqbolli strategik qaror qabul qilish. Misol: &quot;Ertaga havo harorati 40°C bo&#39;lishi kutilmoqda. Shu sababli markaziy savdo nuqtalariga qo&#39;shimcha 1000 dona muzqaymoq yetkazib berish va sovutkichlarni tekshirish buyrug&#39;i berilsin&quot;.</li></ul><hr>',9))]),i("div",g,[i("h2",y,[l(o,{name:"file-text"}),a[6]||(a[6]=t(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-ma-lumot-turlarini-tasniflash-oson" tabindex="-1">1-topshiriq. Ma&#39;lumot turlarini tasniflash (oson) <a class="header-anchor" href="#_1-topshiriq-ma-lumot-turlarini-tasniflash-oson" aria-label="Permalink to &quot;1-topshiriq. Ma&#39;lumot turlarini tasniflash (oson)&quot;">​</a></h3><p>Berilgan misollarni mos ma&#39;lumot turiga (Miqdoriy diskret, Miqdoriy uzluksiz, Sifat, Nostrukturaviy) ajrating:</p><ol><li>Maktabdagi kompyuterlar soni (30 dona).</li><li>Xodimning bir oylik ish safari uchun yoqilg&#39;i sarfi (45.8 litr).</li><li>&quot;Kuryer xizmati juda tez va xushmuomala&quot; degan mijoz sharhi.</li><li>Xavfsizlik kamerasidan olingan 15 soniyalik video yozuv.</li></ol><p><strong>Yechim:</strong></p><ol><li>Miqdoriy diskret (chunki narsalar butun sonlarda sanaladi).</li><li>Miqdoriy uzluksiz (chunki suyuqlik hajmi o&#39;lchanadi va o&#39;nlik kasr bo&#39;lishi mumkin).</li><li>Sifat (chunki tavsifiy matn, hissiyot va fikrni ifodalaydi).</li><li>Nostrukturaviy (chunki video fayl aniq jadval strukturasiga ega emas).</li></ol><h3 id="_2-topshiriq-savdo-jarayonida-dikw-zanjirini-tuzish-o-rta" tabindex="-1">2-topshiriq. Savdo jarayonida DIKW zanjirini tuzish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-savdo-jarayonida-dikw-zanjirini-tuzish-o-rta" aria-label="Permalink to &quot;2-topshiriq. Savdo jarayonida DIKW zanjirini tuzish (o&#39;rta)&quot;">​</a></h3><p>Kiyim-kechak do&#39;koni uchun quyidagi elementlarni DIKW piramidasining to&#39;g&#39;ri bosqichlariga joylashtiring:</p><ul><li>A: &quot;Qish yaqinlashganda va havo harorati 5°C dan pasayganda qalin kurtkalarga talab 3 barobar ortadi&quot;.</li><li>B: &quot;10, 150, kurtka, 05-noyabr&quot;.</li><li>C: &quot;Do&#39;konda 5-noyabr kuni 10 dona kurtka 150 dollardan sotildi&quot;.</li><li>D: &quot;Noyabr oyi boshida kurtkalar zaxirasini 200 taga yetkazish va aksiyani 1-noyabrdan boshlash kerak&quot;.</li></ul><p><strong>Yechim:</strong></p><ul><li>Data (Ma&#39;lumot): B (&quot;10, 150, kurtka, 05-noyabr&quot; — xom qiymatlar).</li><li>Information (Axborot): C (&quot;Do&#39;konda 5-noyabr kuni 10 dona kurtka...&quot; — kontekst berilgan ma&#39;lumot).</li><li>Knowledge (Bilim): A (&quot;Qish yaqinlashganda... talab 3 barobar ortadi&quot; — tahlil va qonuniyat).</li><li>Wisdom (Donolik): D (&quot;Noyabr oyi boshida zaxirani 200 taga yetkazish...&quot; — aniq boshqaruv qarori).</li></ul><h3 id="_3-topshiriq-sensor-ma-lumotlarini-tahlil-qilish-qiyin" tabindex="-1">3-topshiriq. Sensor ma&#39;lumotlarini tahlil qilish (qiyin) <a class="header-anchor" href="#_3-topshiriq-sensor-ma-lumotlarini-tahlil-qilish-qiyin" aria-label="Permalink to &quot;3-topshiriq. Sensor ma&#39;lumotlarini tahlil qilish (qiyin)&quot;">​</a></h3><p>Aqlli issiqxona (Smart Greenhouse) tizimi har 10 daqiqada quyidagi qatorni yozib oladi: <code>{&quot;sensor_id&quot;: &quot;TEMP_01&quot;, &quot;val&quot;: 34.2, &quot;unit&quot;: &quot;C&quot;, &quot;status&quot;: &quot;WARN&quot;, &quot;time&quot;: &quot;14:20&quot;}</code></p><ol><li>Bu ma&#39;lumot qaysi strukturaviy turga kiradi?</li><li>Ushbu ma&#39;lumot qanday qilib Information va Knowledge bosqichlariga aylanadi?</li><li>Wisdom bosqichida qanday avtomatlashtirilgan harakat amalga oshirilishi lozim?</li></ol><p><strong>Yechim:</strong></p><ol><li>Yarim-strukturaviy (Semi-Structured Data), chunki JSON formati orqali kalit-qiymat tuzilmasiga ega.</li><li>Information: &quot;TEMP_01 sensori soat 14:20 da harorat 34.2°C ga ko&#39;tarilganini va bu me&#39;yordan yuqoriligi (WARN)ni qayd etdi&quot;. Knowledge: &quot;Agar issiqxonada harorat soat 14:00 dan 16:00 gacha 32°C dan oshsa, pomidor gullari to&#39;kilishi va hosildorlik 20% ga pasayishi kuzatiladi&quot;.</li><li>Wisdom: Tizim zudlik bilan avtomatik sovutish va soyabon ventilyatorlarini ishga tushiradi hamda agronom telefoniga ogohlantirish xabarini yuboradi.</li></ol><hr>',16))]),i("div",b,[i("h2",v,[l(o,{name:"file-text"}),a[9]||(a[9]=t(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Xom ma’lumot (data) va axborot (information) o‘rtasidagi tub farq nimada? <ul><li><em>Javob:</em> Ma’lumot kontekstsiz xom fakt bo‘lsa, axborot unga kontekst, ma’no va aniq maqsad yuklangan ko‘rinishidir.</li></ul></li><li>Nima sababdan fototasvirlar nostrukturaviy ma’lumot hisoblanadi? <ul><li><em>Javob:</em> Chunki ularda relyatsion jadvallarga xos ustun va satrlar bo‘lmaydi, piksellar majmuasidan iborat.</li></ul></li><li>DIKW modelidagi Knowledge (Bilim) bosqichi qanday savolga javob beradi? <ul><li><em>Javob:</em> &quot;Nima uchun?&quot; (sabab-oqibat bog&#39;liqligi va qonuniyatlar).</li></ul></li></ol><hr>",2))]),i("div",f,[i("h2",c,[l(o,{name:"house"}),a[12]||(a[12]=t(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"O'zingiz qiziqqan biror soha (masalan, futbol jamoasi, mobil o'yin yoki maktab oshxonasi) misolida DIKW piramidasining to'rttala bosqichini (Data, Information, Knowledge, Wisdom) aniq yozib keling.",-1))])])}const S=n(d,[["render",z]]);export{M as __pageData,S as default};
